insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'hs_soc_v1'
from (values
('113.46.c.1.A',3,'Who is credited with coining the term "sociology" in the 1830s?','["Auguste Comte", "Max Weber", "Karl Marx", "Emile Durkheim"]'::jsonb,0,'Comte called for a science of society.','original'),
('113.46.c.1.A',3,'Sociology developed as a field largely in response to what changes?','["The discovery of electricity only", "Industrialization, urbanization and political revolutions", "The invention of the printing press", "Ancient trade routes"]'::jsonb,1,'Rapid social change prompted systematic study of society.','original'),
('113.46.c.1.B',3,'Which sociologist studied suicide rates to show that social forces shape individual behavior?','["Herbert Spencer", "Auguste Comte", "Emile Durkheim", "Harriet Martineau"]'::jsonb,2,'His study "Suicide" is a classic example of sociological method.','original'),
('113.46.c.1.B',3,'Max Weber is best known for introducing which research approach?','["Counting only crime statistics", "Strict laboratory experiments", "Ignoring subjective meaning", "Verstehen, or interpretive understanding of meaning"]'::jsonb,3,'Weber stressed understanding the meanings people attach to actions.','original'),
('113.46.c.1.C',3,'W. E. B. DuBois contributed to sociology by doing what?','["Conducting early empirical studies of African American communities such as The Philadelphia Negro", "Founding the field of anthropology", "Inventing the census", "Writing the first sociology textbook in Europe"]'::jsonb,0,'He used surveys and data to study race and society.','original'),
('113.46.c.1.C',3,'Jane Addams is linked to sociology through which work?','["Writing the Communist Manifesto", "Hull House and social reform for immigrants and the poor", "Developing IQ tests", "Founding the first stock exchange"]'::jsonb,1,'Her settlement house work shaped applied social research.','original'),
('113.46.c.2.A',3,'Which type of society relies mainly on herding animals for food?','["Postindustrial society", "Industrial society", "Pastoral society", "Hunting and gathering society"]'::jsonb,2,'Pastoral societies move with herds.','original'),
('113.46.c.2.A',3,'In which type of society do most people work in factories producing goods using machines?','["Pastoral society", "Agrarian society", "Hunting and gathering society", "Industrial society"]'::jsonb,3,'Mass production defines industrial societies.','original'),
('113.46.c.2.B',3,'A society whose economy is based mainly on information and services is called what?','["Postindustrial society", "Horticultural society", "Pastoral society", "Agrarian society"]'::jsonb,0,'The U.S. economy today is largely service-based.','original'),
('113.46.c.2.B',3,'Which society type still exists today in a few remote regions and relies on foraging?','["Industrial society", "Hunting and gathering society", "Information society", "Postindustrial society"]'::jsonb,1,'Small groups still live this way in places.','original'),
('113.46.c.2.C',3,'Industrialization in the United States led to the growth of what?','["More subsistence farming only", "A decline in immigration", "Cities and factory wage labor", "Fewer cities"]'::jsonb,2,'Workers moved from farms to urban jobs.','original'),
('113.46.c.2.D',3,'Which change best describes cultural life in the United States over the last century?','["All regional differences disappeared", "Culture stopped changing", "Immigration ended", "Mass media spread shared popular culture across regions"]'::jsonb,3,'Radio, television and the internet spread cultural trends.','original'),
('113.46.c.2.D',3,'Comparing cultural life across countries is called what?','["Cross-cultural comparison", "Participant observation only", "Random sampling", "Deviance analysis"]'::jsonb,0,'It reveals similarities and differences.','original'),
('113.46.c.3.A',3,'Which element of culture is a shared system of spoken or written symbols?','["Mores", "Language", "Roles", "Sanctions"]'::jsonb,1,'Language transmits culture.','original'),
('113.46.c.3.A',3,'Cultural values are best described as what?','["Physical objects", "Rules with legal penalties", "Shared ideas about what is good, right and desirable", "Group membership lists"]'::jsonb,2,'Norms reflect values.','original'),
('113.46.c.3.B',3,'Which statement best explains how culture works as a whole?','["Each element exists independently", "Only norms matter", "Culture is made of laws alone", "Language, symbols, norms and values reinforce each other"]'::jsonb,3,'The parts interact to form a coherent way of life.','original'),
('113.46.c.3.B',3,'A norm that carries strong moral weight and is strictly enforced is called what?','["Mores", "Customs", "Folkways", "Fads"]'::jsonb,0,'Mores concern right and wrong.','original'),
('113.46.c.3.C',3,'A subculture is a group that does what?','["Rejects all of society", "Shares some elements of the larger culture but has its own distinct norms or values", "Has no norms", "Is always illegal"]'::jsonb,1,'Skaters and bikers are examples of subcultures.','original'),
('113.46.c.3.C',3,'Which is an example of a subculture?','["A family reunion", "A national government", "Amish communities in the United States", "The entire U.S. population"]'::jsonb,2,'They share U.S. life but keep distinct practices.','original'),
('113.46.c.4.A',3,'A primary group is characterized by what?','["Anonymous interactions", "Short-term contracts", "Large size and impersonal ties", "Small size, close personal ties and long-lasting relationships"]'::jsonb,3,'Family and close friends are primary groups.','original'),
('113.46.c.4.A',3,'A secondary group is best illustrated by what?','["A work team or college class that forms around a goal", "A close circle of childhood friends", "A family", "A couple"]'::jsonb,0,'Secondary groups are goal-oriented and often temporary.','original'),
('113.46.c.4.B',3,'Role conflict occurs when what happens?','["A role is ascribed", "The demands of two roles a person holds clash", "A person has no roles", "Everyone agrees on roles"]'::jsonb,1,'A student who is also a parent may face it.','original'),
('113.46.c.4.B',3,'A reference group is one that people use to do what?','["Avoid all contact", "Elect leaders", "Evaluate their own attitudes and behavior", "Create laws"]'::jsonb,2,'We compare ourselves with those groups.','original'),
('113.46.c.5.A',3,'Which of these is a source of cultural differences in norms within the United States?','["Time zones only", "Alphabet differences", "Currency rates", "Ethnicity and socioeconomic status"]'::jsonb,3,'Norms vary among subgroups.','original'),
('113.46.c.5.A',3,'Ethnocentrism is the practice of what?','["Judging another culture by the standards of your own", "Studying cultures neutrally", "Avoiding all cultures", "Adopting a new culture"]'::jsonb,0,'Cultural relativism is its counterpart.','original'),
('113.46.c.5.B',3,'A stereotype is best described as what?','["A law", "An oversimplified generalization about a group", "A voluntary choice", "A tested scientific fact"]'::jsonb,1,'Stereotypes ignore individual differences.','original'),
('113.46.c.5.B',3,'Stereotypes about subcultures can be harmful because they do what?','["Increase accuracy", "Improve communication", "Lead to unfair treatment of individuals", "Eliminate bias"]'::jsonb,2,'They shape attitudes and discrimination.','original'),
('113.46.c.5.C',3,'Which is a social problem often studied in subcultures?','["Orbital mechanics", "Weather", "Geology", "Gang violence"]'::jsonb,3,'Sociologists examine causes and consequences.','original'),
('113.46.c.5.C',3,'A social problem is generally defined as what?','["A condition many people view as harmful to society and wish to change", "Any personal inconvenience", "A tradition", "A law"]'::jsonb,0,'Poverty and crime are examples.','original'),
('113.46.c.5.D',3,'A counterculture is a group that does what?','["Fully supports dominant norms", "Rejects major values of the dominant culture", "Is formed by government", "Has no members"]'::jsonb,1,'The 1960s hippie movement is an example.','original'),
('113.46.c.5.D',3,'The 1960s counterculture influenced American society by doing what?','["Abolishing the Constitution", "Ending the Cold War", "Challenging norms about war, authority and lifestyle", "Creating the stock market"]'::jsonb,2,'Some changes were later absorbed into the mainstream.','original'),
('113.46.c.6.A',3,'Socialization is best defined as what?','["A genetic process", "A government program", "A type of crime", "The lifelong process of learning the norms, values and roles of a society"]'::jsonb,3,'It is culturally shaped.','original'),
('113.46.c.6.A',3,'Why does socialization differ between cultures?','["Each culture teaches its own norms and values", "Humans are born with identical beliefs", "Governments forbid it", "Biology alone decides"]'::jsonb,0,'What is learned depends on culture.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Social Studies' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'hs_soc_v1'
from (values
('113.46.c.6.B',3,'Which is the most important agent of socialization for young children?','["The mass media", "The family", "The military", "The workplace"]'::jsonb,1,'Family provides the first lessons.','original'),
('113.46.c.6.B',3,'Peer groups are important agents of socialization because they do what?','["Make laws", "Replace schools", "Teach norms among equals and influence adolescent behavior", "Give grades"]'::jsonb,2,'Peers matter strongly in adolescence.','original'),
('113.46.c.6.C',3,'Resocialization occurs when a person does what?','["Remains unchanged", "Joins a primary group only", "Forgets language", "Learns new norms and values, as in boot camp or prison"]'::jsonb,3,'Adults can be socialized again.','original'),
('113.46.c.6.C',3,'Anticipatory socialization is learning what?','["The norms of a role you expect to take on later", "Laws of other countries", "Skills you will never use", "Past roles only"]'::jsonb,0,'A student preparing for college is an example.','original'),
('113.46.c.7.A',3,'Adolescence as a distinct stage developed in part because of what?','["Longer working days for teens", "Compulsory education and child labor laws that kept youth out of the workforce", "The invention of the telephone", "A decline in schooling"]'::jsonb,1,'These changes extended the time between childhood and adulthood.','original'),
('113.46.c.7.A',3,'The juvenile justice system, created around 1900, reflected the belief that young offenders should be what?','["Ignored", "Executed", "Rehabilitated rather than punished as adults", "Sent to adult prisons"]'::jsonb,2,'It recognized adolescence as separate from adulthood.','original'),
('113.46.c.7.B',3,'Which is one of the characteristics of adolescence?','["Retirement", "Complete financial independence", "Marriage by law", "Biological growth and development"]'::jsonb,3,'Puberty is a major biological change.','original'),
('113.46.c.7.B',3,'Identity formation during adolescence involves what?','["Exploring who one is and what one values", "Avoiding peers", "Giving up all choices", "Following only parents"]'::jsonb,0,'It is a key developmental task.','original'),
('113.46.c.7.C',3,'Which is a contemporary issue facing adolescents?','["Pensions", "Dating violence and peer pressure", "Retirement planning", "Property taxes"]'::jsonb,1,'Sociologists study these concerns.','original'),
('113.46.c.7.C',3,'Cyberbullying is a concern for teens because it does what?','["Occurs only at school", "Is always anonymous and harmless", "Can follow them anywhere online and reach large audiences", "Cannot be reported"]'::jsonb,2,'Technology expands bullying.','original'),
('113.46.c.7.D',3,'Which skill helps adolescents make responsible life choices?','["Avoiding goals", "Acting on impulse", "Ignoring advice", "Evaluating consequences before acting"]'::jsonb,3,'Decision-making skills reduce risk.','original'),
('113.46.c.7.D',3,'Resisting negative peer pressure is an example of what?','["Assertiveness", "Conformity", "Deviance", "Role conflict"]'::jsonb,0,'Saying no confidently protects choices.','original'),
('113.46.c.8.A',3,'Which stage of life is typically associated with establishing a career and family?','["Late adulthood", "Early adulthood", "Childhood", "Infancy"]'::jsonb,1,'Many take on work and partner roles.','original'),
('113.46.c.8.A',3,'A difference between men and women in adult development historically included what?','["Identical expectations", "Different alphabets", "Different expectations about work and caregiving roles", "No differences in society"]'::jsonb,2,'Gender roles shaped adult paths.','original'),
('113.46.c.8.B',3,'One way the U.S. labor force has changed in recent decades is that what?','["Women are barred from work", "Manufacturing employs the majority", "Fewer people work in services", "Many more women now work outside the home"]'::jsonb,3,'Women''s participation rose sharply.','original'),
('113.46.c.8.B',3,'The shift from manufacturing to service jobs is called what?','["Deindustrialization", "Colonization", "Urbanization", "Socialization"]'::jsonb,0,'Service work has replaced factory work in many places.','original'),
('113.46.c.8.C',3,'Retirement is a major life change in late adulthood because it does what?','["Guarantees wealth", "Alters income, roles and daily routines", "Eliminates health needs", "Ends all social roles"]'::jsonb,1,'Adjusting to retirement can be difficult.','original'),
('113.46.c.8.C',3,'The aging of the U.S. population places pressure on what?','["School sports leagues only", "Space programs", "Social Security and health care systems", "Weather services"]'::jsonb,2,'More retirees means higher demand.','original'),
('113.46.c.9.A',3,'The functionalist perspective views deviance as what?','["Always meaningless", "Caused only by biology", "A product of class conflict only", "Serving certain functions, such as clarifying social boundaries"]'::jsonb,3,'Durkheim argued deviance is normal.','original'),
('113.46.c.9.A',3,'Labeling theory, an interactionist view, says deviance results from what?','["Society labeling certain acts or people as deviant", "Genetic traits only", "Lack of laws", "Poverty only"]'::jsonb,0,'The label affects self-identity.','original'),
('113.46.c.9.B',3,'Why are crime and arrest rates different across social categories?','["Gender is irrelevant to any statistic", "Opportunity, poverty and differential enforcement all play a role", "Race alone determines crime", "Rates are identical"]'::jsonb,1,'Interpretation requires considering social context.','original'),
('113.46.c.9.B',3,'Which is a limitation of official crime statistics?','["They show motives for all crimes", "They include every crime", "Many crimes go unreported", "They are gathered by sociologists only"]'::jsonb,2,'The "dark figure of crime" is unreported crime.','original'),
('113.46.c.9.C',3,'The main components of the U.S. criminal justice system are police, courts and what?','["Hospitals", "Libraries", "Schools", "Corrections"]'::jsonb,3,'Corrections includes prisons and probation.','original'),
('113.46.c.9.C',3,'Rehabilitation as a goal of corrections aims to do what?','["Help offenders return to society as law-abiding people", "Remove all rights", "Punish severely only", "Ignore the offender"]'::jsonb,0,'It contrasts with retribution.','original'),
('113.46.c.10.A',3,'A caste system is one in which status is what?','["Chosen at age eighteen", "Ascribed at birth and rarely changeable", "Earned by wealth", "Open to everyone"]'::jsonb,1,'Social mobility is very limited.','original'),
('113.46.c.10.A',3,'Social mobility in a class system means what?','["Moving to another state only", "Staying in one class forever", "Movement of a person up or down in social position", "Joining a club"]'::jsonb,2,'Open class systems allow it.','original'),
('113.46.c.10.B',3,'Poverty in the United States is measured partly using what?','["Number of siblings", "Zip code only", "Car ownership", "A poverty line based on income and family size"]'::jsonb,3,'The government sets thresholds.','original'),
('113.46.c.10.B',3,'A long-term effect of poverty on individuals can be what?','["Poorer health and fewer educational opportunities", "Better health outcomes", "Increased social mobility for all", "Higher guaranteed wages"]'::jsonb,0,'Poverty limits life chances.','original'),
('113.46.c.10.C',3,'The functionalist theory of stratification claims that inequality does what?','["Is caused by nature", "Motivates people to fill important jobs", "Has no purpose", "Is always harmful"]'::jsonb,1,'Davis and Moore proposed it.','original'),
('113.46.c.10.C',3,'Conflict theorists argue that stratification does what?','["Does not exist", "Is natural and fair", "Benefits powerful groups at the expense of others", "Benefits everyone equally"]'::jsonb,2,'Marx emphasized class conflict.','original'),
('113.46.c.10.D',3,'Global stratification refers to what?','["Inequality within one family", "Equal wealth worldwide", "Weather patterns", "Unequal distribution of wealth and power among nations"]'::jsonb,3,'It divides high-income and low-income countries.','original'),
('113.46.c.10.D',3,'Which is a characteristic of many low-income nations?','["Higher infant mortality and limited access to education", "Universal health care", "High tech exports only", "Very high literacy everywhere"]'::jsonb,0,'Inequality shapes life chances worldwide.','original'),
('113.46.c.11.A',3,'A minority group in sociology is defined by what?','["Living in cities only", "Having less power and facing unequal treatment, not necessarily being smaller in number", "Always being fewer than half the population", "Having wealth"]'::jsonb,1,'Power, not numbers, is the key.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Social Studies' and d.language = 'en'
on conflict (fingerprint) do nothing;
